const workStatuses = `-- name: WorkStatuses :many
SELECT connection_id, stream, operation, revision, state_version, state, next, observed, observed_completed, observed_total, acknowledged, acknowledged_completed, acknowledged_total, failure FROM work WHERE connection_id=? ORDER BY operation
`

func (q *Queries) WorkStatuses(ctx context.Context, connectionID string) ([]Work, error) {
	rows, err := q.db.QueryContext(ctx, workStatuses, connectionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Work
	for rows.Next() {
		var i Work
		if err := rows.Scan(
			&i.ConnectionID,
			&i.Stream,
			&i.Operation,
			&i.Revision,
			&i.StateVersion,
			&i.State,
			&i.Next,
			&i.Observed,
			&i.ObservedCompleted,
			&i.ObservedTotal,
			&i.Acknowledged,
			&i.AcknowledgedCompleted,
			&i.AcknowledgedTotal,
			&i.Failure,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
